@classmethod
def make_compound_path(cls, *args):
    """Make a compound path from a list of Path objects."""
    # Handle an empty list in args (i.e. no args).
    if not args:
        return Path(np.empty([0, 2], dtype=np.float32))

    vertices = np.concatenate([x.vertices for x in args])
    codes = np.empty(len(vertices), dtype=cls.code_type)
    i = 0
    for path in args:
        if path.codes is None or len(path.codes) == 0:
            codes[i] = cls.MOVETO
            codes[i + 1:i + len(path.vertices)] = cls.LINETO
        else:
            codes[i:i + len(path.codes)] = path.codes

        # Replace internal STOPs with MOVETO for the beginning of each path
        if cls.STOP in path.codes:
            stop_indices = np.where(path.codes == cls.STOP)[0]
            codes[i + stop_indices + 1] = cls.STOP  # Mark last vertex as STOP to avoid internal stops

        i += len(path.vertices)

    # Remove internal STOPs if any exist, keep only one STOP at the end
    if np.sum(codes == cls.STOP) > 1:
        codes = np.where(np.roll(codes, shift=1) == cls.STOP, cls.LINETO, codes)

    return cls(vertices, codes)
