@classmethod
def make_compound_path(cls, *args):
    """Make a compound path from a list of Path objects."""
    # Handle an empty list in args (i.e. no args).
    if not args:
        return Path(np.empty([0, 2], dtype=np.float32))

    # Collect vertices and prepare to build codes
    vertices = np.concatenate([x.vertices for x in args])
    codes = []

    for i, path in enumerate(args):
        if i == 0:
            codes.append(cls.MOVETO)
        else:
            codes.append(cls.LINETO)

        if path.codes is not None:
            # Add path's codes, replacing STOP with a LINETO
            for code in path.codes:
                if code != cls.STOP:
                    codes.append(code)

    # Ensure the path ends with a STOP if there are multiple paths
    if len(args) > 1:
        codes.append(cls.STOP)

    return cls(vertices, np.array(codes, dtype=cls.code_type))
