@classmethod
def make_compound_path(cls, *args):
    """Make a compound path from a list of Path objects."""
    # Handle an empty list in args (i.e. no args).
    if not args:
        return Path(np.empty([0, 2], dtype=np.float32))

    vertices = np.concatenate([x.vertices for x in args])
    codes = np.empty(len(vertices), dtype=cls.code_type)
    i = 0
    for path in args:
        if path.codes is None:
            codes[i] = cls.MOVETO
            codes[i + 1:i + len(path.vertices)] = cls.LINETO
        else:
            codes[i:i + len(path.codes)] = path.codes

        # Remove STOP from internal paths
        if np.any(path.codes == cls.STOP):
            stop_indices = np.where(path.codes == cls.STOP)[0]
            # Only append MOVETO to the codes
            if len(stop_indices) > 0 and stop_indices[0] == 0:
                raise ValueError("Path cannot start with STOP.")
            codes[i:i + len(path.codes)] = np.clip(path.codes, None, cls.STOP)

        i += len(path.vertices)

    # Replace the last segment's STOP with MOVETO if it's present
    if codes[-1] == cls.STOP:
        codes[-1] = cls.MOVETO

    return cls(vertices, codes)
